nta.declaration:
// toy_refresh.xml -- topic 06, P0 toy model (spec/FSM_06.md section 1).
// One frame = one time unit (clock x). Per frame the controller decides OPEN/CLOSED:
//   OPEN  iff  gate (adversarial, nondeterministic) or refresh (t>0, t mod T == 0)
//              or reuse cap (fsl > W  [deployed, GE=false] | fsl >= W  [fixed, GE=true])
// gap = number of consecutive CLOSED frames.  R-refresh  <=>  A[] gap <= R-1.
// Two independent instances: Cgt (as deployed, '>') and Cge (fixed, '>=').
const int T = 15;      // T_refresh
const int W = 4;       // W_maxskip
const int R = (T < W + 1) ? T : W + 1;   // claimed refresh bound = 5
const int CAP = 64;    // counter saturation bound (never reached: fsl <= T)

template.declaration:
clock x;              // time inside the current frame
int[0,T] ph = 0;      // t mod T (refresh phase locked to video start)
bool first = true;    // t == 0
int[0,CAP] fsl = W + 1;   // frames_since_last_open (init forces OPEN at t = 0)
int[0,CAP] gap = 0;   // consecutive CLOSED frames
bool o = false;       // decision of the last frame

void step(int g) {
    bool rf = !first && ph == 0;
    bool cap = GE ? (fsl >= W) : (fsl > W);
    o = (g == 1) || rf || cap;
    if (o) { fsl = 0; gap = 0; }
    else   { fsl = (fsl < CAP) ? fsl + 1 : CAP; gap = (gap < CAP) ? gap + 1 : CAP; }
    ph = (ph + 1) % T;
    first = false;
}

nta.system:
Cgt = Ctrl(false);
Cge = Ctrl(true);
system Cgt, Cge;
